mapper.select:
/** * selectOfwkUpcsdClngList : isry.couns.mngr.workaltmntmng.mapper.OfwkUpcsdClngMapper : 퇴근미처리소명 목록 조회 */ SELECT C##RG.DEC_B64(BB.FLNM_ENCPT) AS CNSLTNT_NM /** 퇴근처리 누락자 **/ , AA.USER_ID AS CNSLTNT_ID , SUBSTR(AA.UNOF_YMD, 1,4)||'-'||SUBSTR(AA.UNOF_YMD, 5,2)||'-'||SUBSTR(AA.UNOF_YMD, 7,2) AS UNOF_YMD /** 미처리 일자 **/ -- , DECODE(AA.REG_YN,'N','미등록','등록완료') AS FLAG_YN /** 상태 (미등록N, 등록Y) **/ -- , DECODE(AA.APRV_STTS_SE_CD,'2','Y','N') AS CMPTN_YN /** 승인 여부 **/ , AA.REG_YN AS FLAG_YN /** 상태 **/ , AA.APRV_STTS_SE_CD AS CMPTN_YN /** 승인 여부 **/ , COUNT(*) OVER() AS TOTAL_COUNT FROM AYC310 AA , SCA100 BB , SAA200 CC WHERE 1=1 AND AA.USER_ID = CC.USER_ID AND CC.ENFSN_NO = BB.ENFSN_NO
AND AA.USER_ID = #{userId}
AND BB.FLNM_ENCPT = C##RG.ENC_B64(#{userNm})
AND AA.REG_YN = #{flagYn}
AND AA.UNOF_YMD >= TO_DATE(#{bgngYmd} || '000000', 'YYYYMMDDHH24MISS')
AND AA.UNOF_YMD < TO_DATE(#{endYmd} || '000000', 'YYYYMMDDHH24MISS')+1
ORDER BY 3 DESC OFFSET #{START_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY /** 페이징 처리 **/

/** * selectOfwkUpcsdClngDetail : isry.couns.mngr.workaltmntmng.mapper.OfwkUpcsdClngMapper : 퇴근미처로소명 상세 조회 */ SELECT C##RG.DEC_B64(BB.FLNM_ENCPT) AS USER_NM /** 퇴근처리 누락자 **/ , SUBSTR(AA.UNOF_YMD, 1, 4)||'-'||SUBSTR(AA.UNOF_YMD, 5, 2)||'-'||SUBSTR(AA.UNOF_YMD, 7, 2) AS UNOF_YMD /** 미처리 일자 **/ , AA.REG_YN AS FLAG_YN /** 상태 (미등록N, 등록Y) **/ , TO_CHAR(AA.FRST_REG_DT,'YYYY-MM-DD') AS REG_YMD /** 자료등록일자 **/ , AA.APRV_STTS_SE_CD AS APRV_STTS_SE_CD /** 승인 여부 **/ , AA.UNOF_CS_CN AS LVFFC_CS_CN /** 누락사유(미퇴근사유내용 in table) **/ , AA.ATFINO AS ATFINO /** 증빙자료 첨부(미퇴근사유파일명 in table) **/ , AA.MDFCN_CS_CN AS MDFCN_CS_CN /** 수정사유 **/ , CC.USER_ID AS USER_ID /** 사용자 아이디 **/ FROM AYC310 AA , SCA100 BB , SAA200 CC WHERE 1=1 AND AA.USER_ID = CC.USER_ID AND CC.ENFSN_NO = BB.ENFSN_NO
AND AA.USER_ID = #{userId}
AND AA.UNOF_YMD = REPLACE(#{unofYmd}, '-', '')

mapper.update:
/**
*		updateOfwkUpcsdClng : isry.couns.mngr.workaltmntmng.mapper.OfwkUpcsdClngMapper :  퇴근미처리소명 저장
*/
		UPDATE 
				AYC310 T1  /* 사이버상담사퇴근관리(퇴근미처리소명) */
		SET
				T1.LAST_MDFCN_DT		= SYSDATE
			,	T1.APRV_STTS_SE_CD		= #{aprvSttsSeCd}
			,	T1.LAST_MDFR_ID			= #{LOGIN_ID}

			,	T1.MDFCN_CS_CN			= #{mdfcnCsCn}


			,	T1.UNOF_CS_CN			= #{lvffcCsCn}


			,	T1.ATFINO				= #{atfino}

		WHERE	1=1
			AND	T1.USER_ID				= #{userId}
			AND	T1.UNOF_YMD				= REPLACE(#{unofYmd}, '-', '')
